🐛 Describe the bug
When initializing the named_parameters(), the code raises memory error once it reaches "norm1.weight".
It happens if we try to use xavier_uniform_() or kaiming_uniform_().
class TestModuleImpl : public torch::nn::Module {
public:
    TestModuleImpl(int numTransformers, int transformerSizes){
        for(int i=0; i<numTransformers; ++i){
            std::string name = std::string("encoderTransformer")+std::to_string(i);
            auto transf = register_module(name, torch::nn::TransformerEncoderLayer(transformerSizes, 2));
            _transformers.push_back(transf);
        }
        for(auto m : modules(false)){  kaimingInit_Layer(m);  }
    }

    void kaimingInit_Layer( const std::shared_ptr<Module>& m ){
        for(auto& p : m->named_parameters()){
            if (p.key().find("weight") != std::string::npos){
                torch::nn::init::kaiming_uniform_(p.value()); // <------------crashes here when "norm1.wieght", Error at mem location.
            }
        }
    }
    std::vector<torch::nn::TransformerEncoderLayer> _transformers;
};
TORCH_MODULE(TestModule);

